import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateProfileHandler } from "../handlers/updateProfileHandler";
import type { ApiError } from "../runtime/client";
import type { UpdateProfileRequest } from "../types/UpdateProfileRequest";

type Data = Awaited<ReturnType<typeof updateProfileHandler>>;
type Vars = UpdateProfileRequest;

export function useUpdateProfile(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateProfileHandler(vars),
    ...options,
  });
}
